import math
Vs, P = 230.0, 2000.0
R = Vs**2 / P
def bracket(a):
    return 1 - a/math.pi + math.sin(2*a)/(2*math.pi)
def alpha_for(p):
    lo, hi = 0.0, math.pi
    for _ in range(200):
        mid = (lo + hi) / 2
        if bracket(mid) > p:
            lo = mid
        else:
            hi = mid
    return (lo + hi) / 2
print(round(R, 2))
for p in (0.5, 0.25):
    v = Vs * math.sqrt(p)
    a = math.degrees(alpha_for(p))
    print(round(v, 2), round(a, 1), round(v / R, 2))
